SourceCode.Declaration:
[DataContractAttribute]
class HSMobileOpsLocationResponse
{
    boolean          success;
    str              errorCode;
    boolean          locationExists;
    boolean          canReceiveInto;
    InventLocationId warehouseId;
    WMSLocationId    locationId;
    str              blockingCause;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

/// <summary>
/// Whether the bin exists at all. Distinct from [parmCanReceiveInto], because "no such bin"
/// and "that bin is blocked" send an operator to two different places.
/// </summary>
[DataMemberAttribute('Exists')]
public boolean parmExists(boolean _value = locationExists)
{
    locationExists = _value;
    return locationExists;
}

[DataMemberAttribute('CanReceiveInto')]
public boolean parmCanReceiveInto(boolean _value = canReceiveInto)
{
    canReceiveInto = _value;
    return canReceiveInto;
}

[DataMemberAttribute('WarehouseId')]
public InventLocationId parmWarehouseId(InventLocationId _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}

[DataMemberAttribute('LocationId')]
public WMSLocationId parmLocationId(WMSLocationId _value = locationId)
{
    locationId = _value;
    return locationId;
}

[DataMemberAttribute('BlockingCause')]
public str parmBlockingCause(str _value = blockingCause)
{
    blockingCause = _value;
    return blockingCause;
}
